/* Penyelesaian penuh UKKM Set 4: Matematik & Sains (dimuat selepas kertas dihantar) */
(window.UKKM_SOL = window.UKKM_SOL || {})[4] = {"mat":["<h5>🧭 Faham soalan</h5><p>Diberi jujukan 2, 9, 28, 65. Cari sebutan selepas 65.</p><h5>💡 Strategi</h5><p>Bandingkan setiap sebutan dengan kuasa tiga nombor mengikut kedudukannya. Pola ini sesuai kerana 2, 9, 28 dan 65 masing-masing satu lebih daripada kuasa tiga.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Sebutan pertama: 1³ + 1 = 1 + 1 = 2; kedua: 2³ + 1 = 8 + 1 = 9.</li><li>Sebutan ketiga: 3³ + 1 = 27 + 1 = 28; keempat: 4³ + 1 = 64 + 1 = 65.</li><li>Sebutan kelima: 5³ + 1 = 125 + 1 = 126.</li><li>Jawapan: <b>D</b> (126).</li></ol><h5>🔍 Semak jawapan</h5><p>126 − 1 = 125 = 5³, jadi pola masih dipatuhi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (102): 102 diperoleh jika hanya menambah beza terakhir, 65 − 28 = 37; pola beza tidak kekal.</li><li><b>B</b> (124): 124 ialah 5³ − 1, sedangkan semua sebutan menggunakan tambah 1.</li><li><b>C</b> (125): 125 ialah 5³ sahaja; tambahan 1 tertinggal.</li></ul><h5>📌 Tip peperiksaan</h5><p>Semak sekurang-kurangnya tiga sebutan sebelum memilih pola jujukan.</p>",
"<h5>🧭 Faham soalan</h5><p>Caj mula RM 4.00, caj jarak RM 1.20 bagi setiap km, dan jumlah bayaran RM 22.00. Cari jarak perjalanan.</p><h5>💡 Strategi</h5><p>Tolak caj tetap dahulu; baki bayaran berkadar terus dengan jarak. Kemudian bahagikan dengan caj bagi 1 km.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bayaran untuk jarak = RM 22.00 − RM 4.00 = RM 18.00.</li><li>Jarak = RM 18.00 ÷ (RM 1.20 setiap km) = 15 km.</li><li>Jawapan: <b>15 km</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>RM 4.00 + 15 × RM 1.20 = RM 4.00 + RM 18.00 = RM 22.00.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Membahagikan RM 22.00 terus dengan RM 1.20 akan memasukkan caj mula sebagai jarak.</li><li>Menolak RM 1.20 sekali sahaja tidak mengambil kira caj bagi setiap kilometer.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan tambang, asingkan caj tetap daripada caj mengikut penggunaan.</p>",
"<h5>🧭 Faham soalan</h5><p>Peniaga membeli 50 biji pada RM 6 sebiji, tetapi hanya 45 biji boleh dijual pada RM 8.40 sebiji. Cari peratus untung.</p><h5>💡 Strategi</h5><p>Peratus untung menggunakan kos pembelian semua tembikai sebagai penyebut, termasuk yang rosak.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Bilangan dijual = 50 − 5 = 45 biji.</li><li>Jumlah kos = 50 × RM 6 = RM 300. Jumlah jualan = 45 × RM 8.40 = RM 378.</li><li>Untung = RM 378 − RM 300 = RM 78. Peratus untung = RM 78 ÷ RM 300 × 100% = 26%.</li><li>Jawapan: <b>B</b> (26%).</li></ol><h5>🔍 Semak jawapan</h5><p>26% × RM 300 = RM 78, sama dengan beza jualan dan kos.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (20.6%): 20.6% hampir kepada RM 78 ÷ RM 378 × 100%; itu membahagi dengan jualan, bukan kos.</li><li><b>C</b> (30%): 30% terhasil jika untung sebiji 40% ditolak terus dengan kadar rosak 10% (5 ÷ 50 × 100%); kedua-dua peratus itu berasaskan kuantiti berbeza dan tidak boleh ditolak begitu. Untung sebenar ialah RM 78 atas kos RM 300, iaitu 26%.</li><li><b>D</b> (40%): 40% ialah untung sebiji tanpa mengambil kira 5 biji yang rosak: (8.40 − 6) ÷ 6 × 100%.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk untung atau rugi, penyebut peratus sentiasa kos asal.</p>",
"<h5>🧭 Faham soalan</h5><p>Pelari menempuh 100 m dalam 12.5 saat. Laju diminta dalam km/j.</p><h5>💡 Strategi</h5><p>Hitung laju dalam m/s, kemudian darab dengan 3.6 kerana 1 m/s = 3.6 km/j.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Laju = jarak ÷ masa = 100 m ÷ 12.5 s = 8 m/s.</li><li>1 jam = 3 600 s dan 1 km = 1 000 m. Maka 8 m/s = 8 × 3 600 ÷ 1 000 km/j = 28.8 km/j.</li><li>Jawapan: <b>C</b> (28.8 km/j).</li></ol><h5>🔍 Semak jawapan</h5><p>28.8 km/j ÷ 3.6 = 8 m/s; dalam 12.5 s jaraknya 8 × 12.5 = 100 m.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (2.22 km/j): 2.22 km/j terhasil apabila 8 dibahagi dengan 3.6; arah penukaran terbalik.</li><li><b>B</b> (8 km/j): 8 ialah laju dalam m/s, belum dalam km/j.</li><li><b>D</b> (480 km/j): 480 diperoleh daripada 8 × 60, iaitu hanya menukar saat kepada minit.</li></ul><h5>📌 Tip peperiksaan</h5><p>Ingat arah penukaran: m/s kepada km/j, darab 3.6.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual memberi saiz kasut 5 hingga 9 dan bilangannya. Cari murid yang saiz kasutnya melebihi mod.</p><h5>💡 Strategi</h5><p>Kenal pasti mod melalui kekerapan paling tinggi, kemudian jumlahkan kekerapan bagi saiz yang lebih besar sahaja.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada jadual, kekerapan saiz 5, 6, 7, 8, 9 ialah 4, 9, 12, 7, 3.</li><li>Kekerapan tertinggi ialah 12, maka mod ialah saiz 7.</li><li>Saiz lebih besar daripada 7 ialah 8 dan 9; bilangannya 7 + 3 = 10 murid.</li><li>Jawapan: <b>A</b> (10).</li></ol><h5>🔍 Semak jawapan</h5><p>Jumlah semua murid = 4 + 9 + 12 + 7 + 3 = 35, sepadan dengan soalan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (12): 12 ialah bilangan murid pada saiz mod itu sendiri.</li><li><b>C</b> (13): 13 = 4 + 9 ialah bilangan murid dengan saiz lebih kecil daripada mod.</li><li><b>D</b> (22): 22 = 12 + 7 + 3 memasukkan saiz 7, sedangkan diminta lebih besar.</li></ul><h5>📌 Tip peperiksaan</h5><p>Mod ialah nilai data dengan kekerapan tertinggi, bukan kekerapan itu sendiri.</p>",
"<h5>🧭 Faham soalan</h5><p>Resipi 24 biji menggunakan 150 g gula. Cari gula untuk 60 biji dengan sukatan yang sama.</p><h5>💡 Strategi</h5><p>Gunakan nisbah terus: apabila bilangan kuih bertambah, jisim gula didarab dengan faktor skala yang sama.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Faktor skala = 60 ÷ 24 = 2.5.</li><li>Gula diperlukan = 150 g × 2.5 = 375 g.</li><li>Jawapan: <b>D</b> (375 g).</li></ol><h5>🔍 Semak jawapan</h5><p>375 ÷ 60 = 6.25 g sebiji; 150 ÷ 24 = 6.25 g sebiji.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (60 g): 60 g diperoleh jika faktor 24 ÷ 60 digunakan secara terbalik.</li><li><b>B</b> (186 g): 186 g = 150 + (60 − 24), tetapi bilangan kuih dan gram tidak boleh ditambah begitu.</li><li><b>C</b> (300 g): 300 g hanya dua kali resipi, cukup untuk 48 biji.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi resipi, cari faktor bilangan hasil dahulu dan darab setiap bahan dengannya.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual memuatkan lima jisim tembikai dalam g dan kg. Cari min jisim dalam kg.</p><h5>💡 Strategi</h5><p>Samakan unit dahulu, kemudian bahagikan jumlah jisim dengan lima data.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>1 200 g = 1 200 ÷ 1 000 = 1.2 kg; 2 400 g = 2.4 kg.</li><li>Jumlah = 1.2 + 2.4 + 2.2 + 2.4 + 2.3 = 10.5 kg.</li><li>Min = 10.5 kg ÷ 5 = 2.1 kg.</li><li>Jawapan: <b>A</b> (2.1 kg).</li></ol><h5>🔍 Semak jawapan</h5><p>2.1 × 5 = 10.5 kg, sama dengan jumlah jisim.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (2.3 kg): 2.3 kg ialah median selepas data disusun, bukan min.</li><li><b>C</b> (2.4 kg): 2.4 kg ialah mod kerana muncul dua kali.</li><li><b>D</b> (2.625 kg): 2.625 kg terhasil jika 10.5 kg dibahagi dengan 4, sedangkan ada lima tembikai.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jangan puratakan nombor yang mempunyai unit berlainan sebelum menukar unit.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan empat sudut sisi empat: 2x, 105°, x + 15° dan 90°. Cari x.</p><h5>💡 Strategi</h5><p>Jumlah sudut pedalaman sisi empat ialah 360°. Bentuk persamaan daripada keempat-empat sudut.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, sudut di P ialah 2x, di Q 105°, di R x + 15°, dan di S 90°.</li><li>2x + 105° + (x + 15°) + 90° = 360°, jadi 3x + 210° = 360°.</li><li>3x = 360° − 210° = 150°; x = 150° ÷ 3 = 50°.</li><li>Jawapan: <b>A</b> (50°).</li></ol><h5>🔍 Semak jawapan</h5><p>Sudutnya 100°, 105°, 65° dan 90°; jumlah = 360°.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (65°): 65° ialah sudut di R selepas x + 15° dikira, bukan x.</li><li><b>C</b> (100°): 100° ialah sudut di P, iaitu 2x.</li><li><b>D</b> (110°): 110° diperoleh jika menggunakan 540°, jumlah sudut pentagon.</li></ul><h5>📌 Tip peperiksaan</h5><p>Kenal pasti jenis poligon sebelum menggunakan jumlah sudut pedalaman.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah menunjukkan segi empat tepat 20 cm × 14 cm dengan semibulatan pada sisi 14 cm. Garis putus-putus di dalam bukan sempadan.</p><h5>💡 Strategi</h5><p>Tambah tiga sisi lurus luar dan lengkok separuh bulatan. Diameter lengkok ialah 14 cm.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jejari semibulatan = 14 ÷ 2 = 7 cm.</li><li>Panjang lengkok = separuh lilitan bulatan = (1 ÷ 2) × 2 × (22 ÷ 7) × 7 = 22 cm.</li><li>Tiga sisi lurus = 20 + 14 + 20 = 54 cm. Perimeter = 54 + 22 = 76 cm.</li><li>Jawapan: <b>B</b> (76 cm).</li></ol><h5>🔍 Semak jawapan</h5><p>76 − 54 = 22 cm, tepat panjang lengkok separuh bulatan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (65 cm): 65 cm menggunakan lengkok 11 cm, iaitu suku bulatan.</li><li><b>C</b> (90 cm): 90 cm = 76 + 14 memasukkan garis putus-putus yang bukan sempadan.</li><li><b>D</b> (98 cm): 98 cm menggunakan lilitan bulatan penuh 44 cm menggantikan lengkok 22 cm.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jejaki sempadan luar dengan jari; jangan kira garis yang berada di dalam bentuk.</p>",
"<h5>🧭 Faham soalan</h5><p>16 September 2026 ialah Rabu. Cari hari bagi 25 Disember 2026.</p><h5>💡 Strategi</h5><p>Hitung sela hari antara dua tarikh, kemudian ambil baki apabila dibahagi dengan tujuh. Setiap tujuh hari, nama hari berulang.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Baki September selepas 16 September = 30 − 16 = 14 hari. Oktober ada 31 hari, November 30 hari, dan hingga 25 Disember ada 25 hari.</li><li>Jumlah sela = 14 + 31 + 30 + 25 = 100 hari.</li><li>100 = 7 × 14 + 2. Dua hari selepas Rabu ialah Khamis, kemudian Jumaat.</li><li>Jawapan: <b>B</b> (Jumaat).</li></ol><h5>🔍 Semak jawapan</h5><p>98 hari ialah tepat 14 minggu selepas Rabu, iaitu Rabu; dua hari lagi ialah Jumaat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Khamis): Khamis ialah satu hari selepas Rabu; itu berlaku jika tersalah kira 99 hari.</li><li><b>C</b> (Sabtu): Sabtu ialah tiga hari selepas Rabu; itu berlaku jika 16 September dikira dua kali.</li><li><b>D</b> (Ahad): Ahad ialah empat hari selepas Rabu, jadi ia memerlukan sela hari dengan baki 4 apabila dibahagi dengan 7, contohnya 102 hari. Sela sebenar ialah 100 hari dan berbaki 2, maka bukan Ahad.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam kiraan sela tarikh, jangan kira tarikh mula sebagai hari tambahan.</p>",
"<h5>🧭 Faham soalan</h5><p>Sebutan ke-4 ialah 23 dan sebutan ke-9 ialah 48 dalam jujukan dengan beza tetap. Cari sebutan ke-25.</p><h5>💡 Strategi</h5><p>Cari beza sepunya menggunakan bilangan langkah antara dua kedudukan, kemudian teruskan ke kedudukan diminta.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Dari sebutan ke-4 ke sebutan ke-9 ada 9 − 4 = 5 langkah. Beza sepunya = (48 − 23) ÷ 5 = 25 ÷ 5 = 5.</li><li>Dari sebutan ke-9 ke ke-25 ada 25 − 9 = 16 langkah. Sebutan ke-25 = 48 + 16 × 5 = 128.</li><li>Jawapan: <b>C</b> (128).</li></ol><h5>🔍 Semak jawapan</h5><p>Sebutan pertama = 23 − 3 × 5 = 8; sebutan ke-25 = 8 + 24 × 5 = 128.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (123): 123 = 48 + 15 × 5, terkurang satu langkah dari kedudukan ke-9 ke ke-25.</li><li><b>B</b> (125): 125 = 25 × 5 mengabaikan nilai sebutan pertama.</li><li><b>D</b> (133): 133 = 8 + 25 × 5 menggunakan 25 langkah, bukannya 24 dari sebutan pertama.</li></ul><h5>📌 Tip peperiksaan</h5><p>Beza nombor kedudukan ialah bilangan langkah antara sebutan.</p>",
"<h5>🧭 Faham soalan</h5><p>Balang penuh dengan madu berjisim 1 500 g. Selepas separuh madu digunakan, jisimnya 900 g. Cari jisim balang kosong.</p><h5>💡 Strategi</h5><p>Perbezaan dua bacaan ialah jisim separuh madu yang dikeluarkan. Gandakan untuk mendapat jisim semua madu.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Separuh madu yang digunakan = 1 500 − 900 = 600 g.</li><li>Madu penuh = 2 × 600 = 1 200 g.</li><li>Balang kosong = 1 500 − 1 200 = 300 g.</li><li>Jawapan: <b>A</b> (300 g).</li></ol><h5>🔍 Semak jawapan</h5><p>Balang dan separuh madu yang tinggal = 300 + 600 = 900 g.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (600 g): 600 g ialah jisim separuh madu, bukan balang.</li><li><b>C</b> (750 g): 750 g = 1 500 ÷ 2 membahagi jisim balang juga, sedangkan hanya madu dibahagi dua.</li><li><b>D</b> (1 200 g): 1 200 g ialah jisim madu penuh.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan jisim bekas yang tetap dengan jisim isi yang berubah.</p>",
"<h5>🧭 Faham soalan</h5><p>Pinjaman RM 12 000 dikenakan faedah sama rata 4% setahun selama 5 tahun. Bayaran dibuat setiap bulan.</p><h5>💡 Strategi</h5><p>Kira faedah atas pokok asal untuk semua tahun, tambah kepada pokok, lalu bahagi dengan jumlah bulan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Faedah setahun = RM 12 000 × 4% = RM 480. Faedah 5 tahun = RM 480 × 5 = RM 2 400.</li><li>Jumlah bayaran balik = RM 12 000 + RM 2 400 = RM 14 400.</li><li>Bilangan bulan = 5 × 12 = 60. Ansuran bulanan = RM 14 400 ÷ 60 = RM 240.</li><li>Jawapan: <b>C</b> (RM 240).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 240 × 60 = RM 14 400, termasuk pokok dan faedah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 200): RM 200 = RM 12 000 ÷ 60, jadi faedah tidak dimasukkan.</li><li><b>B</b> (RM 208): RM 208 = RM 12 480 ÷ 60, hanya memasukkan faedah bagi satu tahun.</li><li><b>D</b> (RM 1 200): RM 1 200 = RM 14 400 ÷ 12, terlupa tempoh lima tahun.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk faedah sama rata, gunakan pokok asal pada setiap tahun.</p>",
"<h5>🧭 Faham soalan</h5><p>Aiman menukar RM 850 pada SGD 1 = RM 3.40, membelanjakan SGD 180, lalu menukar bakinya pada SGD 1 = RM 3.30.</p><h5>💡 Strategi</h5><p>Tukar kepada SGD pada kadar pertama; selepas belanja, darab baki SGD dengan kadar kedua untuk memperoleh RM.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>SGD diterima = RM 850 ÷ (RM 3.40 bagi SGD 1) = SGD 250.</li><li>Baki = SGD 250 − SGD 180 = SGD 70.</li><li>Ringgit diterima = SGD 70 × RM 3.30 = RM 231.</li><li>Jawapan: <b>B</b> (RM 231).</li></ol><h5>🔍 Semak jawapan</h5><p>RM 231 ÷ 3.30 = SGD 70, sama dengan baki selepas perbelanjaan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 21.21): RM 21.21 hampir kepada 70 ÷ 3.30; untuk SGD kepada RM perlu mendarab.</li><li><b>C</b> (RM 238): RM 238 = 70 × 3.40 menggunakan kadar lama.</li><li><b>D</b> (RM 670): RM 670 = 850 − 180 mencampurkan unit RM dengan SGD.</li></ul><h5>📌 Tip peperiksaan</h5><p>Tulis unit mata wang pada setiap langkah supaya arah pertukaran jelas.</p>",
"<h5>🧭 Faham soalan</h5><p>Graf garis menunjukkan jualan Januari hingga Jun. Cari pasangan bulan berturutan dengan kenaikan jualan paling besar.</p><h5>💡 Strategi</h5><p>Baca nilai pada setiap titik graf dan tolak nilai bulan sebelumnya; bandingkan kenaikan positif.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada graf, jualan Januari hingga Jun ialah 120, 150, 135, 180, 210 dan 195 unit.</li><li>Perubahan berturutan: 150 − 120 = 30; 135 − 150 = −15; 180 − 135 = 45; 210 − 180 = 30; 195 − 210 = −15.</li><li>Kenaikan terbesar ialah 45 unit dari Mac ke April.</li><li>Jawapan: <b>B</b> (Mac – April).</li></ol><h5>🔍 Semak jawapan</h5><p>180 − 135 = 45 unit, lebih besar daripada dua kenaikan lain, masing-masing 30 unit.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Januari – Februari): Januari – Februari meningkat 30 unit sahaja.</li><li><b>C</b> (April – Mei): April – Mei mencapai jualan 210 unit, tetapi kenaikannya hanya 30 unit.</li><li><b>D</b> (Mei – Jun): Mei – Jun menurun 15 unit, bukan meningkat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bezakan nilai tertinggi pada graf daripada perubahan paling besar.</p>",
"<h5>🧭 Faham soalan</h5><p>Titik P(3, −1) dipantulkan pada garis y = 2, kemudian dialihkan 4 unit ke kiri dan 1 unit ke atas. Cari koordinat akhir.</p><h5>💡 Strategi</h5><p>Pantulan pada garis mendatar mengekalkan koordinat x dan meletakkan y pada jarak yang sama di seberang garis. Selepas itu, lakukan translasi.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jarak P dari y = 2 ialah 2 − (−1) = 3 unit di bawah garis.</li><li>Imej pantulan ialah 3 unit di atas y = 2, iaitu (3, 2 + 3) = (3, 5).</li><li>Translasi memberi x = 3 − 4 = −1 dan y = 5 + 1 = 6. Imej akhir ialah (−1, 6).</li><li>Jawapan: <b>A</b> ((−1, 6)).</li></ol><h5>🔍 Semak jawapan</h5><p>Titik asal y = −1 dan imej pantulan y = 5 mempunyai titik tengah (−1 + 5) ÷ 2 = 2.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> ((−1, 2)): (−1, 2) terhasil jika P dipantulkan pada paksi-x kepada (3, 1), kemudian ditranslasikan 4 unit ke kiri dan 1 unit ke atas; garis pantulan sepatutnya y = 2, bukan paksi-x.</li><li><b>C</b> ((−7, 0)): (−7, 0) menggunakan pantulan pada paksi-y, bukan garis y = 2.</li><li><b>D</b> ((7, 4)): (7, 4) terhasil jika selepas pantulan kepada (3, 5), translasi dilakukan 4 unit ke kanan dan 1 unit ke bawah, bertentangan dengan arahan ke kiri dan ke atas.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk pantulan pada y = a, semak purata koordinat y asal dan imej ialah a.</p>",
"<h5>🧭 Faham soalan</h5><p>Aina, Balqis dan Chen bermain tiga sukan berlainan dan mempunyai umur berlainan. Tentukan pemain bola jaring daripada petunjuk umur.</p><h5>💡 Strategi</h5><p>Gunakan penyingkiran kes: tentukan pemain badminton dahulu, kemudian bandingkan umur dua orang yang tinggal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pemain badminton lebih tua daripada Balqis, maka Balqis bukan pemain badminton.</li><li>Chen paling muda, maka Chen juga tidak boleh menjadi pemain badminton yang lebih tua daripada Balqis. Jadi Aina bermain badminton.</li><li>Baki sukan renang dan bola jaring untuk Balqis dan Chen. Perenang lebih tua daripada pemain bola jaring; Chen paling muda, maka Balqis berenang dan Chen bermain bola jaring.</li><li>Jawapan: <b>C</b> (Chen).</li></ol><h5>🔍 Semak jawapan</h5><p>Susunan Aina badminton, Balqis renang, Chen bola jaring memenuhi semua petunjuk umur.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Aina): Aina sudah dikenal pasti sebagai pemain badminton.</li><li><b>B</b> (Balqis): Balqis perlu menjadi perenang kerana dia lebih tua daripada Chen.</li><li><b>D</b> (Tidak dapat ditentukan): Maklumat mencukupi; setiap sukan dapat dipadankan kepada seorang murid.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam teka-teki logik, catat pilihan yang mustahil sebelum meneka baki padanan.</p>",
"<h5>🧭 Faham soalan</h5><p>Lima murid ditunjuk dari Amin ke Elly lalu kembali, tanpa mengulang murid hujung. Cari murid pada kali ke-97.</p><h5>💡 Strategi</h5><p>Cari panjang satu kitaran penuh pergi dan balik, kemudian gunakan baki pembahagian nombor giliran.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Satu kitaran ialah Amin, Bala, Chong, Dina, Elly, Dina, Chong, Bala: 8 giliran. Selepas itu kembali kepada Amin.</li><li>97 = 8 × 12 + 1. Jadi selepas 12 kitaran lengkap, giliran ke-97 ialah giliran pertama kitaran baharu.</li><li>Giliran pertama ialah Amin.</li><li>Jawapan: <b>A</b> (Amin).</li></ol><h5>🔍 Semak jawapan</h5><p>Giliran ke-1, ke-9 dan seterusnya setiap tambahan 8 semuanya Amin; 97 − 1 = 96 = 12 × 8.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (Bala): Bala ialah giliran kedua; menganggap pola hanya lima murid boleh menghasilkan pilihan ini.</li><li><b>C</b> (Chong): Chong terhasil jika Amin dikira dua kali dalam satu kitaran sehingga kitaran menjadi 9; 97 = 9 × 10 + 7 dan giliran ke-7 dalam kitaran itu ialah Chong. Kitaran sebenar ialah 8.</li><li><b>D</b> (Dina): Dina terhasil jika Bala tertinggal dalam perjalanan balik sehingga kitaran menjadi 7; 97 = 7 × 13 + 6 dan giliran ke-6 dalam kitaran itu ialah Dina. Bala memang ditunjuk semula dalam perjalanan balik.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi gerakan ulang-alik, jangan kira murid di hujung dua kali berturut-turut.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual mengenakan kadar cukai berbeza bagi setiap julat. Pendapatan naik daripada RM 46 000 kepada RM 58 000. Cari pertambahan cukai.</p><h5>💡 Strategi</h5><p>Hanya bahagian tambahan pendapatan perlu dicukai mengikut julat yang dilaluinya. Pecahkan kenaikan pada sempadan RM 50 000.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kenaikan dalam julat 8% ialah RM 50 000 − RM 46 000 = RM 4 000; cukainya RM 4 000 × 8% = RM 320.</li><li>Kenaikan dalam julat 13% ialah RM 58 000 − RM 50 000 = RM 8 000; cukainya RM 8 000 × 13% = RM 1 040.</li><li>Pertambahan cukai = RM 320 + RM 1 040 = RM 1 360.</li><li>Jawapan: <b>B</b> (RM 1 360).</li></ol><h5>🔍 Semak jawapan</h5><p>Cukai lama = RM 15 000 × 3% + RM 11 000 × 8% = RM 1 330. Cukai baharu = RM 1 330 + RM 1 360 = RM 2 690.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (RM 960): RM 960 = RM 12 000 × 8%; keseluruhan kenaikan tidak berada dalam julat 8%.</li><li><b>C</b> (RM 1 560): RM 1 560 = RM 12 000 × 13%; RM 4 000 yang pertama masih pada 8%.</li><li><b>D</b> (RM 3 860): RM 3 860 mengenakan satu kadar pada seluruh pendapatan lama dan baharu, bukannya mengikut julat.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk cukai berperingkat, pecahkan pendapatan pada setiap sempadan kadar.</p>",
"<h5>🧭 Faham soalan</h5><p>Jadual memberi bilangan buku 1 hingga 5 dengan kekerapan 4, 6, 9, k, 3. Min ialah 3. Cari k.</p><h5>💡 Strategi</h5><p>Gunakan min berwajaran: jumlah hasil darab nilai dengan kekerapan dibahagi jumlah kekerapan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Jumlah kekerapan = 4 + 6 + 9 + k + 3 = 22 + k.</li><li>Jumlah buku = 1 × 4 + 2 × 6 + 3 × 9 + 4 × k + 5 × 3 = 58 + 4k.</li><li>(58 + 4k) ÷ (22 + k) = 3. Maka 58 + 4k = 66 + 3k, lalu k = 8.</li><li>Jawapan: <b>B</b> (8).</li></ol><h5>🔍 Semak jawapan</h5><p>Jika k = 8, jumlah buku = 58 + 32 = 90 dan murid = 22 + 8 = 30; min = 90 ÷ 30 = 3.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (2): 2 terhasil jika k tidak dimasukkan dalam jumlah murid.</li><li><b>C</b> (22): 22 ialah jumlah kekerapan yang sudah diketahui, belum termasuk k.</li><li><b>D</b> (30): 30 ialah jumlah murid selepas k = 8, bukan nilai k.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam jadual kekerapan, jumlahkan kekerapan juga apabila membentuk penyebut min.</p>",
"<h5>🧭 Faham soalan</h5><p>Rajah ialah imej cermin jam yang kelihatan menunjukkan 4:20. Tanda tebal menunjukkan kedudukan 12. Cari masa sebenar.</p><h5>💡 Strategi</h5><p>Cermin menukar kiri dan kanan. Bagi jam analog, masa sebenar dan masa imej berjumlah 12:00.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Daripada rajah, imej jam ialah 4:20.</li><li>Tolak daripada 12:00 dengan meminjam 1 jam: 12:00 = 11:60. Jadi 11:60 − 4:20 = 7:40.</li><li>Masa sebenar ialah 7:40.</li><li>Jawapan: <b>C</b> (7:40).</li></ol><h5>🔍 Semak jawapan</h5><p>Pada 7:40, jarum minit menunjuk angka 8. Dalam cermin ia menunjuk angka 4, iaitu 20 minit.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (4:40): 4:40 hanya menukar minit dan membiarkan jam 4.</li><li><b>B</b> (7:20): 7:20 menukar jam tetapi mengekalkan 20 minit.</li><li><b>D</b> (8:40): 8:40 mengira 12 − 4 dan 60 − 20 secara berasingan tanpa pinjam 1 jam.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk masa imej cermin, tolak daripada 12:00 dan pinjam 1 jam jika minit imej bukan sifar.</p>",
"<h5>🧭 Faham soalan</h5><p>Mula dengan 3 × 10³ sel. Setiap 20 minit, setiap sel berlipat dua. Cari bilangan selepas 4 jam dalam bentuk piawai.</p><h5>💡 Strategi</h5><p>Hitung bilangan tempoh 20 minit, lalu darab bilangan awal dengan kuasa dua bagi setiap pembahagian.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>4 jam = 4 × 60 = 240 minit. Bilangan pembahagian = 240 ÷ 20 = 12.</li><li>Bilangan akhir = 3 × 10³ × 2¹² = 3 000 × 4 096 = 12 288 000.</li><li>Dalam bentuk piawai, 12 288 000 = 1.2288 × 10⁷.</li><li>Jawapan: <b>C</b> (1.2288 × 10⁷).</li></ol><h5>🔍 Semak jawapan</h5><p>1.2288 berada antara 1 dan 10, syarat bentuk piawai; 3 000 × 4 096 = 12 288 000.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (3.6 × 10⁴): 3.6 × 10⁴ = 3 000 × 12; ini menggandakan dengan bilangan kitaran, bukan dengan 2 setiap kitaran.</li><li><b>B</b> (4.8 × 10⁴): 4.8 × 10⁴ = 3 000 × 2⁴; ini mengira empat pembahagian sahaja.</li><li><b>D</b> (2.4576 × 10⁷): 2.4576 × 10⁷ = 3 000 × 2¹³; satu pembahagian terlebih.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi pertumbuhan berganda, bilangan kitaran menjadi kuasa, bukan faktor darab biasa.</p>",
"<h5>🧭 Faham soalan</h5><p>Lilin A bermula 30 cm dan berkurang 2 cm sejam. Lilin B bermula 22 cm dan berkurang 1.2 cm sejam. Cari masa panjangnya sama.</p><h5>💡 Strategi</h5><p>Bina ungkapan panjang selepas t jam dan samakan kedua-duanya. Perbezaan panjang awal ditutup pada kadar beza pemendekan.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Panjang A selepas t jam = 30 − 2t cm. Panjang B = 22 − 1.2t cm.</li><li>Samakan: 30 − 2t = 22 − 1.2t. Maka 30 − 22 = 2t − 1.2t, jadi 8 = 0.8t.</li><li>t = 8 ÷ 0.8 = 10 jam.</li><li>Jawapan: <b>10 jam</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>Selepas 10 jam, A = 30 − 2 × 10 = 10 cm dan B = 22 − 1.2 × 10 = 10 cm.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menggunakan 8 ÷ 2 sahaja mengabaikan pemendekan lilin B.</li><li>Menambah kadar 2 + 1.2 salah kerana kedua-dua lilin memendek serentak; beza panjang berubah pada beza kadar.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jika dua kuantiti bergerak sehala, bandingkan kadar perubahannya dengan menolak.</p>",
"<h5>🧭 Faham soalan</h5><p>Baju RM 45 sehelai. Kedai X memberi 1 percuma bagi 3 dibeli; kedai Y memberi diskaun 25% sehelai. Beli tepat 6 helai.</p><h5>💡 Strategi</h5><p>Hitung bilangan helai yang perlu dibayar di X dan harga diskaun sehelai di Y, kemudian bandingkan jumlah.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Kedai X: bayar 3 helai dan dapat 4; untuk 6 helai, bayar 2 lagi. Jumlah dibayar 5 × RM 45 = RM 225.</li><li>Kedai Y: harga selepas diskaun = RM 45 × (100% − 25%) = RM 45 × 75% = RM 33.75. Jumlah = 6 × RM 33.75 = RM 202.50.</li><li>Beza = RM 225 − RM 202.50 = RM 22.50. Kedai Y lebih murah.</li><li>Jawapan: <b>D</b> (Kedai Y lebih murah sebanyak RM 22.50).</li></ol><h5>🔍 Semak jawapan</h5><p>Kedai X memberi satu helai percuma bernilai RM 45; kedai Y menjimatkan 6 × RM 11.25 = RM 67.50 daripada RM 270, jadi beza penjimatan RM 22.50.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Kedua-dua kedai sama harga): Harga sama hanya jika bilangan baju sesuai dengan kumpulan empat di X; enam helai tidak demikian.</li><li><b>B</b> (Kedai X lebih murah sebanyak RM 22.50): RM 22.50 ialah beza yang betul tetapi arah perbandingan terbalik.</li><li><b>C</b> (Kedai Y lebih murah sebanyak RM 67.50): RM 67.50 ialah penjimatan di Y berbanding harga asal, bukan beza antara dua kedai.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi tawaran beli beberapa percuma satu, kira bilangan barang tepat sebelum membandingkan diskaun.</p>",
"<h5>🧭 Faham soalan</h5><p>Jus P bernisbah sirap:air 1:4 dan jus Q 3:2. Campurkan 500 ml P dengan 250 ml Q. Cari nisbah campuran.</p><h5>💡 Strategi</h5><p>Tukar setiap nisbah kepada isi padu sirap dan air berdasarkan jumlah bahagian, kemudian gabungkan isi padu sejenis.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>P mempunyai 1 + 4 = 5 bahagian. Sirap P = 1 ÷ 5 × 500 = 100 ml; air P = 4 ÷ 5 × 500 = 400 ml.</li><li>Q mempunyai 3 + 2 = 5 bahagian. Sirap Q = 3 ÷ 5 × 250 = 150 ml; air Q = 2 ÷ 5 × 250 = 100 ml.</li><li>Jumlah sirap = 100 + 150 = 250 ml; air = 400 + 100 = 500 ml. Nisbah = 250:500 = 1:2.</li><li>Jawapan: <b>A</b> (1 : 2).</li></ol><h5>🔍 Semak jawapan</h5><p>Jumlah campuran = 250 + 500 = 750 ml, sama dengan 500 + 250 ml asal.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> (2 : 3): 2:3 diperoleh dengan menambah nombor nisbah terus, tanpa mengambil kira isi padu 500 ml dan 250 ml.</li><li><b>C</b> (4 : 11): 4:11 boleh terhasil jika nisbah Q dibaca terbalik sebagai air:sirap.</li><li><b>D</b> (1 : 4): 1:4 ialah nisbah jus P sahaja; Q lebih pekat dan mengubah nisbah campuran.</li></ul><h5>📌 Tip peperiksaan</h5><p>Jangan tambah nisbah terus; tukar kepada kuantiti sebenar dahulu.</p>",
"<h5>🧭 Faham soalan</h5><p>Sepuluh nombor mempunyai min 18 dan julat 20. Setiap nombor didarab 3 lalu ditolak 5. Cari min dan julat baharu.</p><h5>💡 Strategi</h5><p>Operasi yang sama pada setiap data mengubah min secara langsung. Julat ialah beza nilai terbesar dengan terkecil; penolakan yang sama terbatal.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Min baharu = 18 × 3 − 5 = 54 − 5 = 49.</li><li>Jika nilai terbesar ialah M dan terkecil m, julat asal M − m = 20. Julat baharu = (3M − 5) − (3m − 5) = 3(M − m).</li><li>Julat baharu = 3 × 20 = 60.</li><li>Jawapan: <b>D</b> (Min 49, julat 60).</li></ol><h5>🔍 Semak jawapan</h5><p>Menambah 5 kepada setiap data baharu akan memberi min 54; membahagi 3 mengembalikan min 18. Julat 60 ÷ 3 = 20.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (Min 13, julat 15): Min 13 dan julat 15 seolah-olah hanya menolak 5 daripada dua ukuran asal.</li><li><b>B</b> (Min 49, julat 55): Min 49 betul, tetapi julat 55 salah kerana tolak 5 daripada setiap data tidak mengubah beza.</li><li><b>C</b> (Min 54, julat 60): Julat 60 betul, tetapi min 54 terlupa menolak 5.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk transformasi ax + b, min menjadi a × min + b dan julat didarab dengan nilai mutlak a.</p>",
"<h5>🧭 Faham soalan</h5><p>Kuboid berukuran 12 cm × 9 cm × 8 cm. Garis berwarna pada rajah merentang dua bucu bertentangan. Cari lidi lurus terpanjang.</p><h5>💡 Strategi</h5><p>Lidi terpanjang ialah pepenjuru ruang. Gunakan Teorem Pythagoras pada tapak, kemudian bersama tinggi kuboid.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Pepenjuru tapak: √(12² + 9²) = √(144 + 81) = √225 = 15 cm.</li><li>Pepenjuru ruang: √(15² + 8²) = √(225 + 64) = √289 = 17 cm.</li><li>Jawapan: <b>D</b> (17.00 cm).</li></ol><h5>🔍 Semak jawapan</h5><p>17² = 289 = 12² + 9² + 8² = 144 + 81 + 64.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (12.04 cm): 12.04 cm hampir kepada √(9² + 8²), pepenjuru satu muka sisi sahaja.</li><li><b>B</b> (14.42 cm): 14.42 cm hampir kepada √(12² + 8²), pepenjuru muka lain sahaja.</li><li><b>C</b> (15.00 cm): 15.00 cm ialah pepenjuru tapak; tinggi 8 cm belum dimasukkan.</li></ul><h5>📌 Tip peperiksaan</h5><p>Untuk pepenjuru kuboid, kuasakan tiga ukuran sebelum mengambil punca kuasa dua.</p>",
"<h5>🧭 Faham soalan</h5><p>Hari pertama nisbah pelajar:dewasa 5:2, kutipan RM 1 440. Hari kedua jumlah orang sama tetapi kutipan RM 1 800. Cari dewasa hari kedua.</p><h5>💡 Strategi</h5><p>Gunakan nisbah untuk mendapat jumlah pengunjung hari pertama. Kemudian bina persamaan kutipan hari kedua menggunakan jumlah yang sama.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Ambil pelajar hari pertama 5k dan dewasa 2k. Kutipan = 4(5k) + 10(2k) = 40k = 1 440, maka k = 36.</li><li>Jumlah pengunjung = 5 × 36 + 2 × 36 = 180 + 72 = 252.</li><li>Jika d dewasa hari kedua, pelajar = 252 − d. Maka 4(252 − d) + 10d = 1 800, iaitu 1 008 + 6d = 1 800.</li><li>6d = 1 800 − 1 008 = 792; d = 792 ÷ 6 = 132.</li><li>Jawapan: <b>D</b> (132).</li></ol><h5>🔍 Semak jawapan</h5><p>Pelajar hari kedua = 252 − 132 = 120. Kutipan = 120 × RM 4 + 132 × RM 10 = RM 480 + RM 1 320 = RM 1 800.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (72): 72 ialah dewasa hari pertama.</li><li><b>B</b> (90): 90 terhasil jika nisbah 5:2 hari pertama dianggap kekal pada hari kedua.</li><li><b>C</b> (120): 120 ialah pelajar hari kedua, bukan dewasa.</li></ul><h5>📌 Tip peperiksaan</h5><p>Apabila jumlah orang tetap, nyatakan satu kumpulan sebagai jumlah tolak kumpulan lain.</p>",
"<h5>🧭 Faham soalan</h5><p>Arumugam boleh siap sendiri dalam 24 hari. Dia bekerja 4 hari sendiri dan 8 hari bersama Hafiz. Cari tempoh Hafiz bekerja sendiri.</p><h5>💡 Strategi</h5><p>Kira bahagian kerja Arumugam sepanjang 12 hari. Baki kerja dilakukan Hafiz dalam 8 hari; daripada itu cari kadar sehari Hafiz.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Arumugam bekerja selama 4 + 8 = 12 hari. Kadar sehari = 1 ÷ 24 kerja, jadi kerjanya = 12 ÷ 24 = 1/2 kerja.</li><li>Baki yang dibuat Hafiz = 1 − 1/2 = 1/2 kerja dalam 8 hari.</li><li>Kadar Hafiz sehari = (1/2) ÷ 8 = 1/16 kerja. Masa untuk satu kerja = 1 ÷ (1/16) = 16 hari.</li><li>Jawapan: <b>C</b> (16).</li></ol><h5>🔍 Semak jawapan</h5><p>Kerja 4 hari pertama = 4/24 = 1/6. Dalam 8 hari bersama, Arumugam buat 8/24 = 1/3 dan Hafiz 8/16 = 1/2; jumlah 1/6 + 1/3 + 1/2 = 1.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> (8): 8 hari ialah masa Hafiz bekerja bersama, dan dia menyiapkan separuh kerja sahaja.</li><li><b>B</b> (12): 12 hari ialah jumlah masa Arumugam bekerja, bukan masa Hafiz sendiri.</li><li><b>D</b> (24): 24 hari ialah masa Arumugam bekerja sendiri.</li></ul><h5>📌 Tip peperiksaan</h5><p>Dalam soalan kerja, kira pecahan kerja setiap orang, bukan hanya jumlah hari.</p>",
"<h5>🧭 Faham soalan</h5><p>Silinder berjari-jari 7 cm mengandungi air sedalam 12 cm. Bongkah 11 cm × 7 cm × 4 cm tenggelam sepenuhnya. Cari kedalaman baharu.</p><h5>💡 Strategi</h5><p>Bongkah menyesarkan air sebanyak isi padunya. Bahagikan isi padu itu dengan luas tapak silinder untuk mendapat kenaikan aras.</p><h5>✏️ Langkah penyelesaian</h5><ol><li>Isi padu bongkah = 11 × 7 × 4 = 308 cm³.</li><li>Luas tapak silinder = πr² = (22 ÷ 7) × 7² = (22 ÷ 7) × 49 = 154 cm².</li><li>Kenaikan aras air = 308 cm³ ÷ 154 cm² = 2 cm. Kedalaman baharu = 12 + 2 = 14 cm.</li><li>Jawapan: <b>14 cm</b>.</li></ol><h5>🔍 Semak jawapan</h5><p>14 cm lebih rendah daripada tinggi bekas 20 cm, jadi air tidak melimpah. Isi padu kenaikan = 154 × 2 = 308 cm³.</p><h5>⚠️ Kesilapan biasa</h5><ul><li>Menjawab 2 cm sahaja memberikan kenaikan aras, bukan kedalaman baharu.</li><li>Menggunakan tinggi bekas 20 cm sebagai kedalaman asal mengabaikan aras air 12 cm yang diberi.</li></ul><h5>📌 Tip peperiksaan</h5><p>Bagi objek tenggelam, isi padu tersesar sama dengan isi padu objek.</p>"],
"sains":["<h5>🧠 Konsep utama</h5><p>Penyediaan slaid basah bagi spesimen biologi memerlukan teknik yang betul supaya struktur sel dapat diperhatikan dengan jelas di bawah mikroskop cahaya. Apabila meletakkan kaca penutup ke atas spesimen epidermis bawang yang telah dititiskan larutan iodin, kaca penutup disandarkan pada sudut kira-kira 45° menggunakan sebatang jarum tenggek. Kaca penutup kemudiannya diturunkan secara perlahan-lahan ke atas kaca slaid. Langkah ini bertujuan menolak udara keluar secara beransur-ansur dan menghalang pembentukan gelembung udara di bawah kaca penutup. Gelembung udara yang terperangkap akan kelihatan seperti bulatan bergelang hitam tebal di bawah mikroskop dan menghalang pemerhatian jelas struktur sel.</p><h5>✅ Mengapa jawapan A betul</h5><p>Menurunkan kaca penutup secara perlahan-lahan pada satu sudut dengan jarum tenggek berfungsi mengelakkan gelembung udara daripada terperangkap di bawah kaca penutup.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pewarnaan nukleus dan sitoplasma sel dicapai melalui titisan larutan iodin, bukan dengan kaedah menurunkan kaca penutup.</li><li><b>C</b> — Tujuan penyediaan slaid adalah untuk melihat struktur sel dalam keadaan yang elok, bukan sengaja membunuh sel bawang.</li><li><b>D</b> — Saiz imej dibesarkan oleh kanta mata dan kanta objek mikroskop, bukannya oleh kaca penutup.</li></ul><h5>📌 Ingat</h5><p>Sentiasa turunkan kaca penutup pada sudut 45° dengan bantuan jarum tenggek bagi mengelakkan gelembung udara terperangkap pada slaid mikroskop.</p>",
"<h5>🧠 Konsep utama</h5><p>Fotosintesis ialah proses biokimia di mana tumbuhan hijau menghasilkan makanannya sendiri berupa glukosa dengan menyerap tenaga daripada cahaya matahari. Proses ini berlaku di dalam kloroplas yang mengandungi pigmen klorofil. Untuk menjalankan proses ini, tumbuhan memerlukan dua bahan mentah utama dari persekitaran, iaitu gas karbon dioksida dan air. Karbon dioksida meresap masuk dari udara melalui stoma pada daun, manakala air diserap oleh akar dari dalam tanah melalui proses osmosis. Persamaan perkataan fotosintesis ialah: Karbon dioksida + Air → Glukosa + Oksigen (dengan kehadiran cahaya matahari dan klorofil).</p><h5>✅ Mengapa jawapan B betul</h5><p>Karbon dioksida dan air ialah dua bahan mentah (reaktan) yang bertindak balas semasa fotosintesis untuk menghasilkan glukosa serta gas oksigen.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Oksigen dan glukosa ialah hasil (produk) fotosintesis, atau bahan mentah bagi proses respirasi sel.</li><li><b>C</b> — Glukosa ialah hasil makanan yang disintesis semasa fotosintesis dan disimpan sebagai kanji, bukan bahan mentah awal.</li><li><b>D</b> — Oksigen disingkirkan sebagai hasil sampingan ke persekitaran, bukannya bahan mentah yang diserap untuk memulakan fotosintesis.</li></ul><h5>📌 Ingat</h5><p>Bahan mentah fotosintesis ialah karbon dioksida dan air; hasil fotosintesis pula ialah glukosa dan oksigen.</p>",
"<h5>🧠 Konsep utama</h5><p>Tropisme ialah gerak balas pertumbuhan terarah bahagian tumbuhan terhadap suatu rangsangan luaran sehala. Sekiranya arah pertumbuhan bahagian tumbuhan menuju ke arah rangsangan, gerak balas itu dinamakan tropisme positif, manakala pertumbuhan menjauhi rangsangan dinamakan tropisme negatif. Pada pucuk tumbuhan, rangsangan utama yang mempengaruhi arah pertumbuhan ialah cahaya matahari, iaitu fototropisme. Hormon tumbuhan seperti auksin akan terkumpul lebih banyak pada bahagian pucuk yang terlindung daripada cahaya, menyebabkan sel-sel di bahagian teduh memanjang lebih cepat. Ketidakseimbangan pemanjangan ini melengkungkan pucuk ke arah sumber cahaya bagi memaksimumkan penyerapan cahaya untuk fotosintesis.</p><h5>✅ Mengapa jawapan C betul</h5><p>Pucuk pokok keembung membengkok ke arah cahaya yang datang dari tingkap, menunjukkan gerak balas pertumbuhan ke arah cahaya iaitu fototropisme positif.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Geotropisme positif ialah gerak balas pertumbuhan akar ke arah tarikan graviti bumi (ke arah bawah).</li><li><b>B</b> — Hidrotropisme positif ialah gerak balas pertumbuhan akar tumbuhan menuju ke arah punca kelembapan atau air.</li><li><b>D</b> — Fototropisme negatif merujuk kepada pertumbuhan menjauhi arah datangnya cahaya, seperti yang ditunjukkan oleh akar tumbuhan.</li></ul><h5>📌 Ingat</h5><p>Awalan 'foto-' bermaksud cahaya. Pucuk membengkok ke arah cahaya = fototropisme positif; akar membengkok ke arah graviti = geotropisme positif.</p>",
"<h5>🧠 Konsep utama</h5><p>Telinga manusia mempunyai dua fungsi utama yang sangat penting, iaitu sebagai organ pendengaran dan organ pengekal keseimbangan badan. Telinga terbahagi kepada tiga zon: telinga luar, telinga tengah dan telinga dalam. Di bahagian telinga dalam, terdapat struktur yang terdiri daripada tiga tiub separa bulatan yang berserenjang pada satah berbeza, iaitu salur separuh bulat. Salur separuh bulat ini dipenuhi oleh cecair endolimfa serta sel-sel rambut deria khas. Apabila kepala berputar, bendalir bergerak lalu merangsang sel rambut untuk menghasilkan impuls saraf. Impuls dibawa melalui saraf vestibul ke otak untuk membantu mengekalkan keseimbangan. Bahagian lain dalam telinga dalam turut membantu mengesan kedudukan kepala ketika tidak berputar.</p><h5>✅ Mengapa jawapan D betul</h5><p>Salur separuh bulat bertindak khusus mengesan pergerakan putaran kepala dan membantu menentukan kedudukannya bagi membantu mengekalkan keseimbangan tubuh.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Gegendang telinga berfungsi menerima gelombang bunyi dari salur telinga lalu bergetar mengikut frekuensi gelombang tersebut.</li><li><b>B</b> — Koklea mengandungi reseptor deria pendengaran yang menukarkan getaran bunyi kepada impuls saraf untuk dihantar ke otak.</li><li><b>C</b> — Tulang osikel (tukul, andas dan rakap) berfungsi menguatkan getaran bunyi dari gegendang telinga dan memindahkannya ke jendela bujur.</li></ul><h5>📌 Ingat</h5><p>Salur separuh bulat mengawal keseimbangan kedudukan kepala dan badan, manakala koklea berfungsi untuk deria pendengaran.</p>",
"<h5>🧠 Konsep utama</h5><p>Alveolus merupakan pundi udara seni di dalam peparu manusia di mana proses pertukaran gas respirasi berlaku secara resapan ringkas. Kadar resapan gas merentasi permukaan respirasi bergantung kepada ketebalan dinding pemisah, luas permukaan, dan kecerunan kepekatan gas. Dinding alveolus mempunyai adaptasi khusus dengan hanya terbina daripada selapis sel epitelium yang sangat nipis (setebal satu sel). Dinding kapilari darah yang mengelilingi alveolus juga hanya setebal satu sel. Ketebalan yang amat nipis ini memendekkan jarak laluan resapan, membolehkan gas oksigen meresap masuk dengan pantas ke dalam darah dan karbon dioksida meresap keluar ke rongga alveolus.</p><h5>✅ Mengapa jawapan C betul</h5><p>Dinding alveolus yang setebal satu sel memendekkan jarak resapan, memudahkan pertukaran gas oksigen dan karbon dioksida berlaku dengan sangat cepat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Dinding selapis sel sangat nipis dan rapuh, bukan bertujuan untuk menguatkan struktur mekanikal alveolus.</li><li><b>B</b> — Rembesan mukus untuk memerangkap zarah habuk berlaku pada lapisan sel epitelium bersilia di trakea dan bronkus, bukan alveolus.</li><li><b>D</b> — Alveolus tidak bertindak sebagai tempat menyimpan udara, sebaliknya menjadi tapak pertukaran gas yang berterusan semasa pernafasan.</li></ul><h5>📌 Ingat</h5><p>Adaptasi alveolus: Dinding nipis setebal satu sel memendekkan jarak resapan gas; permukaan lembap melarutkan gas oksigen; jaringan kapilari luas mengekalkan kecekapan pertukaran gas.</p>",
"<h5>🧠 Konsep utama</h5><p>Semasa melakukan aktiviti fizikal yang cergas dan pantas seperti lari pecut 100 m, sel-sel otot memerlukan sejumlah besar tenaga dalam tempoh singkat. Sistem peredaran darah tidak sempat membekalkan oksigen yang mencukupi untuk memenuhi keperluan respirasi aerob otot. Akibatnya, sel otot terpaksa menjalankan respirasi anaerob, iaitu penguraian glukosa tanpa kehadiran oksigen yang mencukupi untuk menghasilkan tenaga segera. Tindak balas ini menghasilkan bahan kumuh iaitu asid laktik (Glukosa → Asid laktik + Tenaga). Pengumpulan asid laktik di dalam serat otot menyebabkan kelesuan, kekejangan dan rasa lenguh. Keadaan ini mewujudkan hutang oksigen, di mana atlet terus bernafas pantas dan dalam selepas larian bagi membekalkan oksigen tambahan untuk menguraikan asid laktik di hati.</p><h5>✅ Mengapa jawapan D betul</h5><p>Otot menjalankan respirasi anaerob yang menghasilkan asid laktik (punca kekejangan/lenguh otot), dan pernafasan pantas diperlukan untuk membayar hutang oksigen bagi menyingkirkan asid laktik tersebut.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penghasilan alkohol (etanol) melalui respirasi anaerob berlaku pada organisma yis (penapaian), bukan di dalam otot manusia.</li><li><b>B</b> — Pernafasan laju dan dalam ialah tindak balas fisiologi normal bagi menyingkirkan hutang oksigen, bukan tanda kerosakan peparu.</li><li><b>C</b> — Kepekatan glukosa darah dikawal atur oleh hati dan pankreas; darah tidak kehilangan seluruh glukosanya semasa berlari.</li></ul><h5>📌 Ingat</h5><p>Respirasi anaerob otot: Glukosa → Asid laktik + Tenaga. Asid laktik terkumpul menyebabkan otot lenguh; hutang oksigen dibayar melalui pernafasan dalam selepas larian.</p>",
"<h5>🧠 Konsep utama</h5><p>Kadar nadi menunjukkan bilangan denyutan salur darah arteri per minit yang seiring dengan pengecutan ventrikel jantung semasa mengepam darah ke seluruh tubuh. Berdasarkan jadual, kadar nadi meningkat daripada 72 denyutan seminit semasa rehat kepada 95 semasa berjalan, dan mencapai 140 semasa berlari. Pemboleh ubah dimanipulasikan ialah jenis aktiviti, pemboleh ubah bergerak balas ialah kadar nadi, dan tempoh aktiviti, iaitu 5 minit, dimalarkan. Semasa aktiviti berlari, otot rangka bekerja keras dan mengecut secara aktif, menyebabkan sel memerlukan kadar respirasi sel yang jauh lebih tinggi untuk menjana tenaga. Bagi memenuhi permintaan metabolik ini, jantung perlu berdenyut lebih kuat dan laju untuk mengepam lebih banyak darah beroksigen dan berglukosa ke otot yang aktif, di samping menyingkirkan karbon dioksida dan haba berlebihan dengan cekap.</p><h5>✅ Mengapa jawapan A betul</h5><p>Jantung mengepam darah dengan lebih pantas untuk menghantar lebih banyak oksigen dan glukosa ke sel-sel otot yang sedang giat menjalankan respirasi sel semasa berlari.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Walaupun kehilangan air melalui perpeluhan berlaku, peningkatan serta-merta kadar nadi semasa berlari bukan disebabkan oleh kepekatan darah.</li><li><b>C</b> — Badan menyingkirkan haba melalui perpeluhan dan vasodilatasi salur darah kulit, bukannya dengan memacu denyutan jantung untuk menyejukkannya.</li><li><b>D</b> — Otot memerlukan jumlah tenaga yang jauh lebih tinggi semasa berlari berbanding ketika duduk berehat.</li></ul><h5>📌 Ingat</h5><p>Aktiviti cergas memerlukan lebih banyak tenaga → respirasi sel meningkat → jantung berdenyut lebih laju untuk membekalkan lebih banyak oksigen dan glukosa → kadar nadi meningkat.</p>",
"<h5>🧠 Konsep utama</h5><p>Semasa perkembangan fetus di dalam rahim, plasenta bertindak sebagai organ perantaraan penting yang menghubungkan peredaran darah ibu dengan fetus melalui tali pusat. Plasenta membolehkan resapan nutrien, oksigen dan antibodi daripada darah ibu ke dalam darah fetus, serta resapan bahan kumuh dari fetus ke ibu. Walaupun sel darah ibu dan fetus tidak bercampur secara terus, bahan kimia berbahaya yang larut di dalam plasma darah ibu boleh meresap merentasi membran plasenta. Asap rokok mengandungi pelbagai toksin berbahaya seperti nikotin yang menyebabkan pengecutan salur darah tali pusat, serta karbon monoksida yang mengikat hemoglobin darah ibu dan fetus, sekali gus mengurangkan bekalan oksigen kepada fetus dan menjejaskan tumbesarannya.</p><h5>✅ Mengapa jawapan C betul</h5><p>Bahan toksik daripada asap rokok seperti nikotin dan gas karbon monoksida boleh meresap merentasi plasenta ke dalam peredaran darah fetus lalu membahayakan janin.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Ovulasi sememangnya terhenti secara semula jadi semasa kehamilan akibat kepekatan hormon progesteron yang tinggi, bukan dihalang oleh asap rokok.</li><li><b>B</b> — Asap rokok tidak merosakkan integriti fizikal sehingga memutuskan tali pusat yang dilindungi oleh jeli Wharton dan bendalir amnion.</li><li><b>D</b> — Gas karbon monoksida bersaing dengan oksigen untuk membentuk karboksihemoglobin, mengakibatkan pengurangan bekalan oksigen kepada fetus.</li></ul><h5>📌 Ingat</h5><p>Bahan kimia berbahaya seperti nikotin, karbon monoksida dan alkohol boleh meresap merentasi plasenta, membawa risiko kelahiran pramatang dan perkembangan terbantut pada fetus.</p>",
"<h5>🧠 Konsep utama</h5><p>Penyakit berjangkit berpunca daripada pelbagai mikroorganisma patogen seperti bakteria, virus, kulat dan protozoa. Ubat antibiotik merupakan sebatian kimia khusus yang direka untuk membunuh bakteria atau merencat pertumbuhannya, contohnya dengan merosakkan sintesis dinding sel atau menghalang replikasi bakteria. Sebaliknya, virus tidak mempunyai struktur sel, sitoplasma, mahupun dinding sel, sebaliknya hanya terdiri daripada bebenang bahan genetik (DNA atau RNA) yang diselaputi lapisan kapsid protein. Virus membiak dengan cara menawan sel perumah. Oleh sebab virus tiada struktur sel atau proses metabolik yang disasarkan oleh antibiotik, antibiotik sama sekali tidak berkesan terhadap jangkitan virus seperti selesema biasa.</p><h5>✅ Mengapa jawapan A betul</h5><p>Selesema biasa disebabkan oleh virus (seperti rhinovirus), dan antibiotik tidak berkesan terhadap virus kerana antibiotik hanya menyasarkan bakteria.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Antibiotik berkesan terhadap bakteria; ubat yang khusus membunuh kulat dikenali sebagai ubat antikulat.</li><li><b>C</b> — Selesema ialah penyakit yang sangat mudah berjangkit melalui titisan cecair udara semasa batuk atau bersin.</li><li><b>D</b> — Antibiotik tidak boleh menukarkan virus menjadi bakteria kerana kedua-duanya tergolong dalam entiti mikroorganisma yang sama sekali berbeza.</li></ul><h5>📌 Ingat</h5><p>Antibiotik hanya membunuh atau merencat pertumbuhan bakteria. Penyakit akibat virus (selesema, influenza, denggi) tidak boleh dirawat menggunakan antibiotik.</p>",
"<h5>🧠 Konsep utama</h5><p>Kitar karbon mengekalkan keseimbangan gas karbon dioksida di atmosfera melalui proses pengambilan dan pembebasan karbon yang berterusan. Tumbuhan hijau di kawasan hutan bertindak sebagai sinki karbon semula jadi yang menyerap sejumlah besar gas karbon dioksida daripada atmosfera melalui fotosintesis untuk membina biojisim. Sebaliknya, proses respirasi sel, pereputan bahan organik dan pembakaran membebaskan gas karbon dioksida kembali ke atmosfera. Apabila hutan ditebang secara besar-besaran, jumlah pokok berkurang dengan mendadak, menyebabkan kadar penyerapan karbon dioksida melalui fotosintesis merosot teruk. Pada masa yang sama, pembakaran kayu membebaskan semula karbon yang tersimpan dalam pokok ke atmosfera sebagai gas karbon dioksida.</p><h5>✅ Mengapa jawapan A betul</h5><p>Penebangan hutan mengurangkan fotosintesis manakala pembakaran kayu membebaskan gas karbon dioksida tambahan, menyebabkan kepekatan gas tersebut di atmosfera melonjak tinggi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Kurangnya bilangan pokok akibat penebangan menyebabkan penghasilan gas oksigen melalui fotosintesis berkurang, bukannya meningkat.</li><li><b>C</b> — Pembakaran kayu memusnahkan simpanan karbon pepejal dalam tisu tumbuhan lalu membebaskannya ke atmosfera sebagai gas.</li><li><b>D</b> — Penebangan dan pembakaran hutan merupakan faktor utama yang mengganggu kitar karbon dan meningkatkan gas rumah hijau di atmosfera.</li></ul><h5>📌 Ingat</h5><p>Tumbuhan hijau menyerap CO₂ melalui fotosintesis; penebangan dan pembakaran hutan membebaskan CO₂ dan mengurangkan penyerapannya, memacu pemanasan global.</p>",
"<h5>🧠 Konsep utama</h5><p>Haiwan dikelaskan kepada dua kumpulan utama: vertebrata (haiwan yang bertulang belakang) dan invertebrata (haiwan yang tidak bertulang belakang). Invertebrata pula dibahagikan kepada invertebrata tanpa kaki dan invertebrata berkaki. Invertebrata berkaki yang paling luas dan berjaya di Bumi tergolong dalam filum Artropod. Ciri sepunya bagi kumpulan artropod ialah mempunyai badan bersegmen, anggota kaki yang bersendi, serta diselaputi oleh rangka luar keras yang dibina daripada bahan kitin. Rangka luar ini berfungsi melindungi organ dalaman, memberi sokongan struktur, dan mencegah kehilangan air berlebihan dari tubuh haiwan. Labah-labah tergolong dalam kelas araknid (kumpulan artropod) yang memiliki empat pasang kaki bersendi dan rangka luar kitin.</p><h5>✅ Mengapa jawapan C betul</h5><p>Labah-labah ialah invertebrata yang tergolong dalam kumpulan artropod, mempunyai rangka luar berkitin dan kaki yang bersendi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Cacing tanah ialah invertebrata tanpa kaki berbadan lembut (annelid) yang mempunyai rangka hidrostatik, bukannya rangka luar keras.</li><li><b>B</b> — Lintah ialah invertebrata tanpa kaki yang berbadan lembut dan tidak mempunyai anggota kaki bersendi.</li><li><b>D</b> — Obor-obor ialah invertebrata akuatik berbadan lembut (knidaria) tanpa kaki bersendi mahupun rangka luar.</li></ul><h5>📌 Ingat</h5><p>Ciri khas artropod (termasuk labah-labah, serangga, ketam, udang): invertebrata yang mempunyai kaki bersendi dan diselaputi rangka luar berkitin.</p>",
"<h5>🧠 Konsep utama</h5><p>Ekosistem terdiri daripada komuniti organisma hidup yang saling berinteraksi dengan persekitaran fizikal bukan hidupnya. Faktor-faktor dalam ekosistem dikelaskan kepada faktor biotik (komponen hidup seperti tumbuhan, haiwan, kulat dan bakteria) serta faktor abiotik (komponen bukan hidup seperti keamatan cahaya, suhu, kelembapan, ketersediaan air dan pH tanah). Dalam penyiasatan ini, bilangan rumput di bawah pokok rendang ialah 8 pokok, manakala di kawasan terbuka ialah 45 pokok. Pemboleh ubah dimanipulasikan ialah kawasan yang dibandingkan (rendang atau terbuka), pemboleh ubah bergerak balas ialah bilangan pokok rumput, dan luas kuadrat 1 m² dimalarkan. Rumput ialah organisma pengeluar autotrof yang memerlukan tenaga cahaya matahari untuk menjalankan fotosintesis bagi membina makanan dan membesar. Kawasan terbuka menerima keamatan cahaya matahari yang jauh lebih tinggi berbanding kawasan di bawah kanopi pokok yang terlindung dan redup.</p><h5>✅ Mengapa jawapan B betul</h5><p>Keamatan cahaya ialah faktor abiotik (bukan hidup); kawasan terbuka menerima lebih banyak cahaya matahari yang menggalakkan fotosintesis dan pertumbuhan rumput yang lebih padat.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Cacing tanah ialah organisma hidup, maka ia tergolong sebagai faktor biotik dan bukannya faktor abiotik.</li><li><b>C</b> — Kulat ialah organisma hidup (pengurai), menjadikannya sebahagian daripada faktor biotik persekitaran.</li><li><b>D</b> — Burung merupakan hidupan haiwan, iaitu faktor biotik dan bukannya faktor abiotik.</li></ul><h5>📌 Ingat</h5><p>Faktor biotik = hidupan (haiwan, tumbuhan, mikroorganisma); Faktor abiotik = komponen fizikal bukan hidupan (cahaya, suhu, air, udara, tanah).</p>",
"<h5>🧠 Konsep utama</h5><p>Menurut Teori Kinetik Jirim, semua jirim terbina daripada zarah-zarah halus dan diskret yang sentiasa berada dalam keadaan bergerak secara berterusan dan rawak. Dalam keadaan gas, zarah-zarah mempunyai tenaga kinetik yang tinggi, tersusun sangat berjauhan antara satu sama lain, dan daya tarikan antara zarah adalah sangat lemah. Keadaan ini membolehkan zarah-zarah gas meluncur dan bergerak bebas ke semua arah. Fenomena di mana zarah-zarah sesuatu bahan bergerak dari kawasan berkepekatan tinggi ke kawasan berkepekatan rendah secara rawak dikenali sebagai resapan. Sebatian meruap berbau durian tersejat menjadi gas berkepekatan tinggi di dapur, lalu zarah-zarahnya meresap melalui ruang antara zarah udara sehingga sampai ke ruang tamu.</p><h5>✅ Mengapa jawapan A betul</h5><p>Zarah-zarah gas bau durian sentiasa bergerak secara rawak dan meresap dari dapur (kepekatan tinggi) ke ruang tamu (kepekatan rendah).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Zarah-zarah jirim tidak membesar atau mengembang; hanya jarak antara zarah yang bertambah luas apabila meresap.</li><li><b>C</b> — Resapan zarah gas berlaku ke semua arah secara rawak akibat perlanggaran antara molekul, walaupun di dalam bilik tanpa tiupan angin.</li><li><b>D</b> — Udara bertindak sebagai medium campuran fizikal zarah bau, bukan bertukar sifat kimianya menjadi zarah durian.</li></ul><h5>📌 Ingat</h5><p>Resapan ialah pergerakan rawak zarah dari kawasan berkepekatan tinggi ke kawasan berkepekatan rendah. Resapan berlaku paling pantas dalam keadaan gas.</p>",
"<h5>🧠 Konsep utama</h5><p>Jadual Berkala Unsur merupakan satu susunan sistematik semua unsur kimia mengikut tertib pertambahan nombor proton (nombor atom). Susunan ini membolehkan saintis meramal sifat fizik dan tindak balas kimia setiap unsur. Dalam Jadual Berkala Unsur, lajur menegak (dari atas ke bawah) dikenali sebagai Kumpulan, yang bernombor dari Kumpulan 1 hingga Kumpulan 18. Unsur dalam kumpulan yang sama lazimnya mempunyai bilangan elektron valens yang sama dan sifat kimia yang serupa; helium ialah pengecualian bagi bilangan elektron valens dalam Kumpulan 18. Sebaliknya, baris mendatar (dari kiri ke kanan) dalam Jadual Berkala dipanggil Kala, yang menunjukkan bilangan petala berisi elektron dalam sesuatu atom.</p><h5>✅ Mengapa jawapan B betul</h5><p>Lajur menegak dalam Jadual Berkala Unsur dinamakan kumpulan (Kumpulan 1 hingga 18) di mana unsur-unsur di dalamnya mempunyai sifat kimia serupa.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kala ialah nama bagi baris mendatar dalam Jadual Berkala Unsur (terdapat 7 kala secara keseluruhan).</li><li><b>C</b> — Istilah 'baris' ialah perkataan am untuk jajaran mendatar; istilah saintifik rasminya dalam Jadual Berkala ialah kala.</li><li><b>D</b> — Sebatian ialah bahan kimia yang terdiri daripada gabungan dua atau lebih jenis unsur secara kimia, bukan istilah struktur jadual.</li></ul><h5>📌 Ingat</h5><p>Lajur menegak = KUMPULAN (sifat kimia serupa); Baris mendatar = KALA (bilangan petala terisi elektron sama).</p>",
"<h5>🧠 Konsep utama</h5><p>Udara atmosfera mengandungi pelbagai jenis gas seperti nitrogen, oksigen, karbon dioksida dan gas nadir yang mempunyai sifat kimia berbeza. Ujian pengesahan gas di dalam makmal sains bergantung kepada sifat kimia khusus setiap gas tersebut. Gas oksigen merupakan komponen utama yang menyokong proses pembakaran. Bagi menguji kehadiran gas oksigen, sebatang kayu uji berbara (kayu uji yang dinyalakan kemudian ditiup apinya sehingga hanya tinggal bara merah) dimasukkan ke dalam tabung uji. Apabila kayu uji berbara dimasukkan ke dalam persekitaran yang kaya dengan gas oksigen, gas oksigen membekalkan sokongan pembakaran yang kuat menyebabkan bara tersebut menyala semula menjadi nyalaan api yang marak.</p><h5>✅ Mengapa jawapan D betul</h5><p>Gas X ialah oksigen kerana oksigen menyokong pembakaran dan membolehkan kayu uji berbara menyala semula dengan api yang terang.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Gas nitrogen tidak menyokong pembakaran dan akan menyebabkan bara kayu uji padam serta-merta.</li><li><b>B</b> — Gas karbon dioksida tidak menyokong pembakaran (memadamkan bara kayu uji) dan ujian pengesahannya adalah mengeruhkan air kapur.</li><li><b>C</b> — Ujian pengesahan bagi gas hidrogen menggunakan kayu uji bernyala yang akan menghasilkan bunyi letupan kecil 'pop'.</li></ul><h5>📌 Ingat</h5><p>Kayu uji berbara menyala semula = Oksigen; Kayu uji bernyala menghasilkan bunyi 'pop' = Hidrogen; Air kapur bertukar keruh = Karbon dioksida.</p>",
"<h5>🧠 Konsep utama</h5><p>Air paip semula jadi mengandungi pelbagai jenis bendasing yang boleh dikelaskan kepada zarah pepejal terampai (kelodak, pasir), bahan kimia terlarut (ion mineral kalsium dan magnesium) serta mikroorganisma patogen. Bagi penyediaan larutan kimia dan eksperimen berkejituan tinggi di makmal, air mestilah bebas daripada sebarang garam galian dan bendasing terlarut. Penyulingan ialah proses pemisahan fizikal di mana air dididihkan sehingga bertukar menjadi stim (wap air), kemudian wap air tersebut disejukkan dan dimeluwapkan semula menjadi titisan cecair di dalam kondensor Liebig. Oleh kerana mineral dan garam terlarut mempunyai takat didih yang sangat tinggi berbanding air, bendasing ini tertinggal di dalam kelalang penyulingan, menghasilkan air suling yang tulen.</p><h5>✅ Mengapa jawapan C betul</h5><p>Penyulingan menyingkirkan kedua-dua bahan pepejal terampai dan bahan mineral terlarut serta kuman, menghasilkan air paling tulen (air suling) untuk kegunaan makmal.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Penurasan hanya menyingkirkan zarah pepejal terampai yang tidak larut, manakala garam mineral terlarut dan bakteria tetap menembusi kertas turas.</li><li><b>B</b> — Pendidihan membunuh mikroorganisma tetapi membiarkan semua mineral terlarut kekal di dalam air.</li><li><b>D</b> — Pengklorinan hanya membunuh kuman penyakit tetapi tidak menyingkirkan mineral terlarut mahupun zarah terampai.</li></ul><h5>📌 Ingat</h5><p>Antara kaedah dalam pilihan jawapan, penyulingan paling sesuai untuk mendapatkan air tulen kerana bahan terlarut dan zarah ampaian tertinggal apabila wap air dikondensasikan.</p>",
"<h5>🧠 Konsep utama</h5><p>Tindak balas peneutralan berlaku apabila suatu asid bertindak balas dengan suatu alkali untuk menghasilkan garam dan air. Persamaan umum bagi tindak balas ini ialah: Asid + Alkali → Garam + Air. Dalam penyiasatan ini, larutan natrium hidroksida (alkali kuat) pada mulanya dititiskan penunjuk fenolftalein sehingga bertukar menjadi warna merah jambu. Fenolftalein berwarna merah jambu dalam larutan beralkali dan menjadi tidak berwarna apabila pH turun di bawah kira-kira 8.2, termasuk dalam larutan neutral atau berasid. Apabila asid hidroklorik ditambah, ion hidrogen (H⁺) bertindak balas dengan ion hidroksida (OH⁻) membentuk air; ion natrium dan klorida membentuk garam natrium klorida. Hilangnya warna merah jambu menunjukkan larutan tidak lagi cukup beralkali untuk mengekalkan warna penunjuk. Warna itu sahaja tidak membuktikan pH tepat-tepat 7.</p><h5>✅ Mengapa jawapan A betul</h5><p>Asid hidroklorik bertindak balas dengan natrium hidroksida dalam tindak balas peneutralan yang menghasilkan natrium klorida dan air; hilangnya warna merah jambu selaras dengan penurunan kealkalian.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Penambahan asid hidroklorik mengurangkan kealkalian larutan dan boleh menjadikannya neutral atau berasid jika asid ditambah berlebihan, bukannya bertambah alkali.</li><li><b>C</b> — Fenolftalein hanya bertindak sebagai penunjuk perubahan nilai pH larutan dan tidak bertindak balas menghasilkan sebarang gas.</li><li><b>D</b> — Natrium hidroksida telah bertindak balas secara kimia membentuk garam natrium klorida, bukannya bertukar menjadi asid kuat.</li></ul><h5>📌 Ingat</h5><p>Peneutralan: Asid + Alkali → Garam + Air. Fenolftalein berwarna merah jambu dalam alkali dan tidak berwarna apabila pH turun di bawah kira-kira 8.2; perubahan warna tidak menentukan pH 7 dengan tepat.</p>",
"<h5>🧠 Konsep utama</h5><p>Pengekstrakan logam besi daripada bijihnya (hematit, ferum(III) oksida) dijalankan di dalam relau bagas pada suhu yang amat tinggi. Tiga bahan mentah utama yang dimasukkan dari bahagian atas relau bagas ialah bijih besi, kok (karbon) dan batu kapur (kalsium karbonat, CaCO₃). Bijih besi mengandungi bendasing utama iaitu silikon dioksida (pasir, SiO₂) yang bersifat asid. Batu kapur ditambah untuk membersihkan bendasing ini. Pada suhu tinggi, batu kapur terurai secara terma menghasilkan kalsium oksida dan karbon dioksida (CaCO₃ → CaO + CO₂). Kalsium oksida (bes) kemudiannya bertindak balas dengan silikon dioksida untuk membentuk kalsium silikat atau sanga (CaO + SiO₂ → CaSiO₃) yang terapung di atas leburan besi.</p><h5>✅ Mengapa jawapan B betul</h5><p>Batu kapur terurai membentuk kalsium oksida yang bertindak balas dengan pasir untuk menyingkirkannya dalam bentuk sanga (kalsium silikat).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Kok (karbon) berfungsi sebagai bahan api untuk membekalkan haba dan menghasilkan karbon monoksida sebagai agen penurunan bijih besi.</li><li><b>C</b> — Udara panas ditiup masuk dari bahagian bawah relau bagas untuk membakar kok bagi mengekalkan suhu tindak balas yang sangat tinggi.</li><li><b>D</b> — Hematit ialah bijih besi utama yang diekstrak untuk menghasilkan leburan besi mentah yang masih mengandungi bendasing, bukannya bahan penyingkir bendasing.</li></ul><h5>📌 Ingat</h5><p>Bahan relau bagas: Hematit = sumber besi; Kok = agen penurunan dan bahan api; Batu kapur = menyingkirkan pasir membentuk sanga.</p>",
"<h5>🧠 Konsep utama</h5><p>Tindak balas kimia melibatkan perubahan tenaga haba dan dikelaskan kepada tindak balas eksotermik dan tindak balas endotermik. Tindak balas eksotermik membebaskan tenaga haba ke persekitaran semasa tindak balas berlangsung, menyebabkan suhu campuran tindak balas meningkat. Sebaliknya, tindak balas endotermik menyerap tenaga haba daripada persekitaran, menyebabkan suhu campuran tindak balas menurun. Pada graf suhu melawan masa, kedua-dua campuran bermula pada kira-kira 28 °C. Suhu P meningkat ke kira-kira 38 °C pada minit ke-4 sebelum menurun, manakala suhu Q turun ke kira-kira 20 °C pada minit ke-4 sebelum meningkat semula. Bagi perbandingan P dengan Q, jenis campuran tindak balas ialah pemboleh ubah dimanipulasikan, perubahan suhu ialah pemboleh ubah bergerak balas, dan suhu awal kira-kira 28 °C adalah sama bagi kedua-duanya.</p><h5>✅ Mengapa jawapan C betul</h5><p>Tindak balas P ialah eksotermik kerana suhunya meningkat (membebaskan haba), manakala tindak balas Q ialah endotermik kerana suhunya menurun (menyerap haba).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Q bukan eksotermik kerana graf suhunya menunjukkan penurunan ke paras 20 °C, bukannya kenaikan suhu.</li><li><b>B</b> — Pernyataan ini terbalik; kenaikan suhu pada P menunjukkan proses eksotermik dan penurunan suhu pada Q menunjukkan proses endotermik.</li><li><b>D</b> — P bukan endotermik kerana tindak balas endotermik menyerap haba dan mengakibatkan penurunan bacaan suhu persekitaran.</li></ul><h5>📌 Ingat</h5><p>Eksotermik = haba dibebaskan, suhu campuran NAIK. Endotermik = haba diserap, suhu campuran TURUN.</p>",
"<h5>🧠 Konsep utama</h5><p>Dalam litar elektrik selari, setiap komponen atau mentol disambungkan pada cabang litarnya yang tersendiri merentasi punca bekalan voltan. Ciri utama litar selari ialah beza keupayaan (voltan) yang merentasi setiap cabang selari adalah sama dengan beza keupayaan bateri (V = V1 = V2). Selain itu, arus elektrik yang mengalir melalui sesuatu cabang ditentukan sepenuhnya oleh rintangan komponen pada cabang itu mengikut hukum Ohm (I = V ÷ R). Berdasarkan rajah skematik, suis S disambungkan secara bersiri secara khusus pada cabang mentol M2 sahaja. Mentol M1 berada pada cabang selari yang berasingan dan masih bersambung secara terus kepada terminal bateri. Apabila suis S dibuka, litar hanya terputus pada cabang M2, manakala cabang M1 tidak terjejas.</p><h5>✅ Mengapa jawapan D betul</h5><p>Membuka suis S hanya memutuskan arus ke mentol M2; mentol M1 masih menerima voltan penuh daripada bateri maka arus melaluinya dan kecerahannya tidak berubah.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Mentol M1 tidak padam kerana laluannya masih lengkap tersambung kepada bateri; mentol yang padam ialah M2.</li><li><b>B</b> — Kecerahan M1 tidak malap kerana voltan yang merentasinya kekal sama seperti sebelumnya.</li><li><b>C</b> — Mentol M1 tidak menjadi lebih terang kerana beza keupayaan yang dibekalkan oleh bateri kepada laluannya tidak meningkat.</li></ul><h5>📌 Ingat</h5><p>Dalam litar selari, setiap beban elektrik beroperasi secara bebas. Membuka suis pada satu cabang tidak menjejaskan operasi atau kecerahan mentol pada cabang yang lain.</p>",
"<h5>🧠 Konsep utama</h5><p>Transformer ialah alat elektrik yang digunakan untuk mengubah (menaikkan atau menurunkan) nilai voltan arus ulang-alik berdasarkan prinsip aruhan elektromagnet. Transformer terdiri daripada gegelung primer (input) dan gegelung sekunder (output) yang dililit pada teras besi lembut berlamina. Hubungan antara voltan primer (Vp), voltan sekunder (Vs), bilangan lilitan gegelung primer (Np) dan bilangan lilitan gegelung sekunder (Ns) dinyatakan oleh rumus: Vp ÷ Vs = Np ÷ Ns. Bagi transformer injak turun, voltan sekunder adalah lebih kecil daripada voltan primer (Vs < Vp), maka bilangan lilitan gegelung sekunder juga mestilah lebih kecil daripada gegelung primer (Ns < Np). Diberi Vp = 240 V, Vs = 12 V, dan Np = 2000 lilitan.</p><h5>✅ Mengapa jawapan A betul</h5><p>Menggunakan rumus transformer: Ns = (Vs ÷ Vp) × Np = (12 ÷ 240) × 2000 = (1 ÷ 20) × 2000 = 100 lilitan.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — 120 lilitan akan memberikan nisbah 120 ÷ 2000 = 0.06, sedangkan nisbah voltannya ialah 12 ÷ 240 = 0.05; kedua-dua nisbah mesti sama.</li><li><b>C</b> — Nilai 1000 lilitan terhasil jika nisbah voltan disalah anggap sebagai pengurangan separuh daripada voltan primer.</li><li><b>D</b> — Nilai 40 000 lilitan diperoleh jika formula diterbalikkan (240 ÷ 12 × 2000), iaitu pengiraan bagi transformer injak naik.</li></ul><h5>📌 Ingat</h5><p>Rumus transformer: Ns ÷ Np = Vs ÷ Vp. Untuk transformer injak turun, voltan output berkurang dan bilangan lilitan sekunder mestilah lebih sedikit daripada primer.</p>",
"<h5>🧠 Konsep utama</h5><p>Daya geseran ialah daya yang menentang pergerakan relatif antara dua permukaan yang bersentuhan. Apabila dua permukaan menggelongsor antara satu sama lain, geseran gelongsor yang wujud boleh menyebabkan kehausan bahan logam, pembaziran tenaga kinetik kepada haba, dan memperlahankan pergerakan. Untuk mengatasi masalah ini dalam jentera dan kenderaan, galas bebola digunakan pada gandar roda yang berputar. Galas bebola mengandungi bebola keluli bulat kecil yang bergolek di antara aci dalam dan perumah luar. Bebola ini menggantikan geseran gelongsor dengan geseran bergolek yang mempunyai nilai daya geseran yang jauh lebih rendah, membolehkan putaran berlaku dengan lancar dan mudah.</p><h5>✅ Mengapa jawapan C betul</h5><p>Galas bebola menukarkan geseran gelongsor kepada geseran bergolek yang jauh lebih kecil, sekali gus mengurangkan geseran agar roda basikal dapat berputar dengan lancar.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Menambah geseran untuk memberhentikan basikal adalah fungsi pad brek, bukan galas bebola.</li><li><b>B</b> — Galas bebola direka bentuk seringan dan secekap mungkin, bukannya bertujuan untuk menambah jisim atau berat basikal.</li><li><b>D</b> — Penyerapan hentakan daripada permukaan jalan yang tidak rata dilakukan oleh sistem spring suspensi atau tayar getah, bukan galas bebola.</li></ul><h5>📌 Ingat</h5><p>Galas bebola mengurangkan geseran dengan menukarkan geseran gelongsor kepada geseran bergolek yang jauh lebih kecil pada gandar berputar.</p>",
"<h5>🧠 Konsep utama</h5><p>Pengaliran haba melalui pepejal berlaku secara konduksi terma. Bahan jirim dikelaskan kepada dua kumpulan utama berdasarkan kekonduksian habanya: konduktor haba dan penebat haba (konduktor haba yang lemah). Konduktor haba yang baik, seperti logam aluminium, besi dan kuprum, membenarkan tenaga haba merambat melaluinya dengan cepat kerana mempunyai zarah yang tersusun rapat serta zarah elektron bebas yang mudah memindahkan tenaga getaran. Sebaliknya, bahan bukan logam seperti kayu dan plastik keras merupakan konduktor haba yang lemah kerana tiada elektron bebas dan zarahnya memindahkan getaran haba dengan sangat perlahan. Oleh itu, bahan penebat ini sangat selamat digunakan sebagai pemegang kuali untuk melindungi tangan manusia daripada melecur.</p><h5>✅ Mengapa jawapan D betul</h5><p>Plastik keras dan kayu ialah penebat haba (konduktor haba lemah) yang menghalang haba panas daripada badan kuali mengalir ke tangan pengguna.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Logam ialah konduktor haba yang baik; sebaliknya plastik dan kayu ialah konduktor haba yang sangat lemah (penebat).</li><li><b>B</b> — Pemantulan haba merupakan sifat permukaan yang berkilat dan berwarna cerah, bukannya sifat utama bahan plastik atau kayu.</li><li><b>C</b> — Plastik dan kayu mempunyai ketumpatan yang lebih rendah dan lebih ringan berbanding bahan logam seperti besi atau tembaga.</li></ul><h5>📌 Ingat</h5><p>Peralatan memasak menggabungkan dua sifat: badan kuali daripada logam (konduktor haba baik untuk memasak cepat) dan pemegang kuali daripada plastik/kayu (penebat haba agar selamat dipegang).</p>",
"<h5>🧠 Konsep utama</h5><p>Cahaya matahari yang kelihatan putih sebenarnya merupakan cahaya polikromatik yang terdiri daripada tujuh juzuk warna spektrum tampak (merah, jingga, kuning, hijau, biru, indigo dan ungu). Setiap juzuk warna mempunyai panjang gelombang dan kelajuan yang berbeza apabila merambat merentasi medium lut sinar seperti kaca atau air. Fenomena pemisahan cahaya putih kepada komponen warna-warnanya dikenali sebagai penyebaran cahaya. Apabila cahaya matahari mengenai titisan air hujan di atmosfera sejurus selepas hujan, titisan air tersebut bertindak sebagai prisma optik semula jadi. Cahaya matahari mengalami pembiasan semasa memasuki titisan air, mengalami pantulan dalaman di permukaan belakang titisan, dan dibiaskan sekali lagi semasa keluar ke udara, menghasilkan spektrum pelangi.</p><h5>✅ Mengapa jawapan A betul</h5><p>Pelangi terbentuk akibat penyebaran cahaya putih oleh titisan air hujan kepada tujuh juzuk warna spektrum yang berbeza sudut pembiasannya.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>B</b> — Pantulan cahaya oleh awan hanya menyebabkan awan kelihatan putih atau gelap, bukan membentuk lengkungan spektrum warna pelangi.</li><li><b>C</b> — Penyerakan cahaya oleh molekul gas dan zarah debu menerangkan fenomena warna langit biru pada waktu siang atau langit merah pada waktu senja.</li><li><b>D</b> — Penyerapan cahaya oleh titisan air mengurangkan keamatan cahaya, bukannya memisahkan komponen warna spektrum tampak.</li></ul><h5>📌 Ingat</h5><p>Pembentukan pelangi adalah disebabkan penyebaran cahaya putih. Titisan air hujan bertindak seperti prisma: cahaya merah paling kurang terbias manakala cahaya ungu paling banyak terbias.</p>",
"<h5>🧠 Konsep utama</h5><p>Gelombang bunyi dihasilkan oleh objek yang bergetar. Dua sifat utama sensasi bunyi ialah kenyaringan dan kelangsingan. Kenyaringan bunyi berkait secara langsung dengan amplitud getaran gelombang bunyi; semakin besar tenaga atau daya yang dikenakan pada objek yang bergetar, semakin besar amplitud getaran dan semakin nyaring bunyi yang dihasilkan (diukur dalam unit desibel, dB). Sebaliknya, kelangsingan bunyi ditentukan oleh frekuensi gelombang (diukur dalam unit hertz, Hz). Dalam eksperimen ini, pemboleh ubah manipulasi ialah daya petikan tali (perlahan, sederhana, kuat) dan pemboleh ubah bergerak balas ialah aras bunyi dalam dB (55 dB, 68 dB, 80 dB), dan tali gitar yang digunakan dimalarkan. Bacaan meningkat daripada 55 dB bagi petikan perlahan kepada 80 dB bagi petikan kuat.</p><h5>✅ Mengapa jawapan B betul</h5><p>Berdasarkan data eksperimen, peningkatan kekuatan petikan menghasilkan aras bunyi (dB) yang lebih tinggi, mengesahkan hipotesis bahawa semakin kuat tali dipetik, semakin tinggi kenyaringan bunyi.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Daya petikan mempengaruhi amplitud gelombang (kenyaringan), bukannya frekuensi getaran (kelangsingan) yang ditentukan oleh ketegangan, tebal dan panjang tali.</li><li><b>C</b> — Panjang tali ialah pemboleh ubah dimalarkan dalam eksperimen ini kerana penyiasatan menggunakan seutas tali gitar yang sama.</li><li><b>D</b> — Data jadual membuktikan secara jelas bahawa aras kenyaringan bunyi bergantung secara langsung kepada kekuatan daya petikan tali.</li></ul><h5>📌 Ingat</h5><p>Kenyaringan bunyi bergantung kepada amplitud gelombang bunyi (dan daya getaran); Kelangsingan bunyi bergantung kepada frekuensi getaran tali.</p>",
"<h5>🧠 Konsep utama</h5><p>Tenaga kinetik ialah tenaga yang dimiliki oleh sesuatu objek akibat daripada pergerakannya. Sebarang objek yang mempunyai jisim dan bergerak dengan suatu halaju mempunyai tenaga kinetik. Formula pengiraan tenaga kinetik (Ek) dinyatakan sebagai Ek = ½ × m × v², di mana m mewakili jisim objek dalam unit kilogram (kg) dan v mewakili halaju pergerakan objek dalam unit meter per saat (m s⁻¹). Unit piawai SI bagi tenaga ialah joule (J). Berdasarkan maklumat soalan, jisim bola m = 0.5 kg dan halaju bola v = 4 m s⁻¹. Langkah pengiraan tenaga kinetik: Kuasa dua halaju terlebih dahulu: v² = 4² = 16 m² s⁻². Kemudian masukkan nilai ke dalam formula: Ek = ½ × 0.5 × 16 = 0.25 × 16 = 4 J.</p><h5>✅ Mengapa jawapan C betul</h5><p>Melalui pengiraan formula tenaga kinetik Ek = ½mv² = ½ × 0.5 × (4)² = ½ × 0.5 × 16 = 4 J.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Nilai 1 J terhasil jika halaju tidak dikuasaduakan dan formula disalah guna sebagai ½ × m × v = ½ × 0.5 × 4 = 1 J.</li><li><b>B</b> — Nilai 2 J ialah hasil darab momentum (m × v = 0.5 × 4 = 2 kg m s⁻¹), bukannya tenaga kinetik.</li><li><b>D</b> — Nilai 8 J terhasil jika faktor pecahan ½ diabaikan daripada rumus tenaga kinetik (m × v² = 0.5 × 16 = 8 J).</li></ul><h5>📌 Ingat</h5><p>Formula Tenaga Kinetik: Ek = ½mv². Jangan lupa menguasaduakan nilai halaju (v²) terlebih dahulu sebelum mendarab dengan jisim dan ½.</p>",
"<h5>🧠 Konsep utama</h5><p>Keradioaktifan ialah proses pereputan spontan dan rawak bagi nukleus atom yang tidak stabil untuk memancarkan sinaran radioaktif bagi mencapai kestabilan. Tiga bentuk sinaran radioaktif utama ialah sinaran alfa (α), beta (β) dan gama (γ). Zarah alfa terdiri daripada gabungan dua proton dan dua neutron, yang sama tepat dengan struktur nukleus bagi atom helium (iaitu ⁴₂He tanpa elektron). Oleh sebab zarah alfa mengandungi dua proton dan tiada elektron bersekutu, zarah alfa membawa cas elektrik positif (+2) dan mempunyai nombor jisim sebanyak 4 unit jisim atom. Ciri fizikal zarah alfa termasuk mempunyai kuasa pengionan yang paling tinggi tetapi mempunyai kuasa penembusan yang rendah, di mana pergerakannya boleh dihentikan oleh sehelai kertas.</p><h5>✅ Mengapa jawapan B betul</h5><p>Zarah alfa ialah nukleus helium yang terdiri daripada dua proton dan dua neutron, menjadikannya zarah bercas positif (+2).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Elektron berkelajuan tinggi yang dipancarkan daripada nukleus semasa pereputan radioaktif ialah zarah beta (β).</li><li><b>C</b> — Gelombang elektromagnet berfrekuensi dan bertenaga amat tinggi yang tidak bercas ialah sinar gama (γ).</li><li><b>D</b> — Neutron yang tidak bercas ialah zarah subatom neutral, bukan identiti zarah alfa.</li></ul><h5>📌 Ingat</h5><p>Sinaran radioaktif: Zarah alfa (α) = nukleus helium (cas positif); Zarah beta (β) = elektron berkelajuan tinggi (cas negatif); Sinar gama (γ) = gelombang elektromagnet (neutral).</p>",
"<h5>🧠 Konsep utama</h5><p>Sistem fizikal planet Bumi dibahagikan kepada empat sfera utama yang saling bersandaran dan berinteraksi antara satu sama lain untuk menyokong kehidupan. Empat sfera tersebut ialah atmosfera, hidrosfera, geosfera dan biosfera. Atmosfera ialah lapisan udara yang menyelubungi permukaan Bumi. Hidrosfera merangkumi semua bahagian air di Bumi termasuk lautan, sungai, tasik, air bawah tanah dan ais glasier. Geosfera merangkumi bahagian zon pepejal Bumi yang terdiri daripada batuan, mineral, kerak bumi dan tanah. Biosfera merujuk kepada seluruh zon kehidupan di planet Bumi, yang merangkumi semua hidupan seperti tumbuhan, haiwan, manusia dan mikroorganisma yang mendiami daratan, lautan dan atmosfera.</p><h5>✅ Mengapa jawapan D betul</h5><p>Biosfera ialah sistem Bumi yang merangkumi semua komuniti hidupan dan habitatnya di daratan (geosfera), air (hidrosfera) dan udara (atmosfera).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Atmosfera ialah lapisan campuran gas dan udara yang menyelubungi planet Bumi, bukan sistem benda hidup.</li><li><b>B</b> — Hidrosfera merangkumi seluruh jasad air cecair dan ais di planet Bumi.</li><li><b>C</b> — Geosfera merujuk kepada zon fizikal pepejal Bumi seperti batuan, tanah dan lapisan mantel serta kerak bumi.</li></ul><h5>📌 Ingat</h5><p>Empat sfera sistem Bumi: Biosfera (hidupan), Atmosfera (udara), Hidrosfera (air), Geosfera (batuan dan tanah pejal).</p>",
"<h5>🧠 Konsep utama</h5><p>Meteoroid ialah jasad batuan atau logam kecil yang terapung dan beredar mengelilingi Matahari di angkasa lepas. Apabila sesuatu meteoroid melintasi berhampiran Bumi, daya tarikan graviti Bumi menarik jasad tersebut masuk ke dalam lapisan atmosfera pada halaju yang sangat tinggi (antara 11 hingga 72 km s⁻¹). Pada kelajuan supersonik yang melampau ini, meteoroid mengalami rintangan dan geseran mampatan udara yang amat kuat dengan molekul gas di atmosfera (terutamanya di lapisan mesosfera). Geseran dan mampatan ini menjana tenaga haba yang sangat tinggi sehingga membakar dan meleburkan meteoroid tersebut, menghasilkan jalur cahaya terang yang dikenali sebagai meteor (atau tahi bintang).</p><h5>✅ Mengapa jawapan B betul</h5><p>Meteoroid terbakar akibat geseran dan mampatan udara pada kelajuan yang sangat tinggi di atmosfera yang menjana haba terlampau panas.</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Tarikan graviti Bulan tidak menyumbang kepada pemanasan atau pembakaran jasad meteoroid yang memasuki ruang udara Bumi.</li><li><b>C</b> — Bilangan satelit di angkasa sangat terhad berbanding ruang atmosfera yang luas, dan pembakaran bukan disebabkan oleh pertembungan satelit.</li><li><b>D</b> — Lapisan ozon berfungsi menyerap radiasi sinaran ultraungu (UV) daripada Matahari, bukan menyerap atau membakar batuan meteoroid.</li></ul><h5>📌 Ingat</h5><p>Perbezaan istilah: Meteoroid = jasad batuan di angkasa; Meteor = lintasan cahaya panas terbakar di atmosfera; Meteorit = serpihan batu yang sampai ke permukaan Bumi.</p>",
"<h5>🧠 Konsep utama</h5><p>Warna sesuatu bintang mencerminkan suhu permukaannya berdasarkan prinsip fizik sinaran jasad hitam. Bintang yang memancarkan tenaga haba pada suhu paling tinggi akan memancarkan cahaya pada panjang gelombang yang lebih pendek dan berfrekuensi tinggi, menjadikannya kelihatan berwarna biru atau biru-putih. Sebaliknya, bintang yang bersuhu lebih sejuk memancarkan panjang gelombang yang lebih panjang, menjadikannya kelihatan berwarna merah atau jingga. Urutan suhu permukaan bintang daripada yang paling panas kepada yang paling sejuk mengikut warnanya ialah: Biru (> 25 000 K) → Biru-putih (10 000 – 25 000 K) → Putih → Kuning (5 000 – 6 000 K) → Jingga → Merah (< 3 500 K). Berdasarkan data soalan: Rigel berwarna biru-putih, Matahari berwarna kuning, dan Betelgeuse berwarna merah.</p><h5>✅ Mengapa jawapan D betul</h5><p>Susunan suhu permukaan daripada tertinggi kepada terendah ialah Rigel (biru-putih, paling panas) > Matahari (kuning, sederhana) > Betelgeuse (merah, paling sejuk).</p><h5>❌ Mengapa pilihan lain salah</h5><ul><li><b>A</b> — Bintang merah seperti Betelgeuse mempunyai suhu permukaan terendah, bukannya tertinggi.</li><li><b>B</b> — Matahari bersuhu sederhana dan lebih sejuk berbanding bintang biru-putih seperti Rigel.</li><li><b>C</b> — Susunan ini meletakkan Betelgeuse lebih panas daripada Matahari, sedangkan bintang merah lebih sejuk daripada bintang kuning.</li></ul><h5>📌 Ingat</h5><p>Urutan warna bintang dari paling panas ke paling sejuk: Biru → Putih → Kuning → Jingga → Merah. Bintang biru-putih (Rigel) lebih panas daripada kuning (Matahari) dan merah (Betelgeuse).</p>"]};
